{
  "intro": "Brief script to read aloud: three short readouts and a closing question.",
  "sections": {
    "strengths": {
      "title": "Concrete representation and real-life link",
      "body": "Point to the moment when the teacher used a cake analogy and shading to make partitions meaningful for students; note the student connection that followed.",
      "say_this": "I noticed how you used the cake example and shading to show partitions — when you said, 'For example, think of it as a cake... we share parts,' students connected the idea to their own lives."
    },
    "growth": {
      "title": "Turn validations into next-step feedback",
      "body": "Show that after a student answer the teacher gives a brief, actionable instruction that tells the learner what to do or check next instead of only affirming or restating.",
      "say_this": "You often confirm answers. Try adding a short, specific step after each reply, for example: 'Good — now check how many of those parts are shaded, then compare that to the total.'"
    },
    "action": {
      "title": "Use a simple feedback script in the lesson",
      "body": "Ask the teacher to use the scripted phrase after student turns for the remainder of the lesson and agree to watch it used in the next classroom visit or observation.",
      "say_this": "In your next lesson try this script after a student's answer: 'Thank you — you counted the parts; now name the shaded parts and tell the total so we can write the fraction.' We'll look for that together during the upcoming observation."
    }
  },
  "reflection_question": "How will you phrase the short feedback step you will use after a student's answer in your next lesson so students know exactly what to do next?",
  "outro": "Close by naming the clear strength you saw (concrete cake model) and the concrete move to try (scripted next-step feedback)."
}
